          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "children": [
        {
          "text": "Tools > Compiler chooses between the LaTeX engine and Typst, and ",
          "marks": [],
          "type": "Text"
        },
        {
          "text": "Compiler status",
          "marks": [
            "bold"
          ],
          "type": "Text"
        },
        {
          "text": " tells you whether the engine and its offline package cache are ready. Everything compiles offline, straight after installation.",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "level": 1,
      "children": [
        {
          "text": "Where to go next",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "children": [
        {
          "text": "Open the ",
          "marks": [],
          "type": "Text"
        },
        {
          "text": "Examples",
          "marks": [
            "bold"
          ],
          "type": "Text"
        },
        {
          "text": " tab for starting points: articles in one, two or three columns, journal papers, theses and books, lab reports, letters, a CV, slides, posters and planners. Each opens in its own window so this tour stays open. The Help tab has the user guide (F1) and every keyboard shortcut.",
          "marks": [],
          "type": "Text"
        }
