      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "latex": "k_{\\mathrm{eff}} = k_m\\,\\frac{k_f + 2k_m + 2\\phi\\,(k_f - k_m)}{k_f + 2k_m - \\phi\\,(k_f - k_m)}.",
      "numbered": true,
      "label": "eq:maxwell",
      "type": "MathBlock"
    },
    {
      "children": [
        {
          "text": "With ",
          "marks": [],
          "type": "Text"
