          "latex": "k_f",
          "type": "MathInline"
        },
        {
          "text": " is the only free parameter. It is found by minimising",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "latex": "\\chi^2(k_f) = \\sum_{i=1}^{N}\\left(\\frac{k_i - k_{\\mathrm{eff}}(\\phi_i; k_f)}{\\sigma_i}\\right)^2,",
      "numbered": true,
      "label": "eq:chi2",
      "type": "MathBlock"
    },
    {
      "children": [
        {
          "text": "over the ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "N = 5",
          "type": "MathInline"
        },
        {
          "text": " filled samples, where ",
          "marks": [],
          "type": "Text"
        },
