        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "latex": "t^{*}=\\frac{v_{0}}{g}\\approx 1.22 \\mathrm{s}, h(t^{*})=h_{0}+\\frac{v_{0}^{2}}{2g}\\approx 8.84 \\mathrm{m}.",
      "numbered": false,
      "label": null,
      "type": "MathBlock"
    },
    {
      "children": [
        {
          "text": "The ball lands when ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "h(t)=0",
          "type": "MathInline"
        },
        {
          "text": ". Here ",
          "marks": [],
          "type": "Text"
