      "latex": "t=\\frac{-12-\\sqrt{173.4}}{2(-4.905)}\\approx 2.57 \\mathrm{s}.",
      "numbered": false,
      "label": null,
      "type": "MathBlock"
    },
    {
      "level": 1,
      "children": [
        {
          "text": "4 ",
          "marks": [],
          "type": "Text"
        },
        {
          "text": "Several variables",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "children": [
        {
          "text": "Completing the square also locates the stationary point of a quadratic form. For a real symmetric matrix ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "A",
          "type": "MathInline"
        },
        {
          "text": ", a vector ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "\\mathbf{b}",
          "type": "MathInline"
        },
        {
          "text": " and a scalar ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "c",
          "type": "MathInline"
        },
        {
          "text": ", consider",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "latex": "q(\\mathbf{x})={\\mathbf{x}}^{⊤}A\\mathbf{x}+2{\\mathbf{b}}^{⊤}\\mathbf{x}+c.",
      "numbered": true,
      "label": null,
      "type": "MathBlock"
    },
    {
      "children": [
        {
          "text": "If ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "A",
          "type": "MathInline"
        },
        {
          "text": " is invertible, ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "q",
          "type": "MathInline"
        },
        {
          "text": " has a unique stationary point at ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "{\\mathbf{x}}^{*}=-A^{-1}\\mathbf{b}",
          "type": "MathInline"
        },
        {
          "text": ", where it takes the value ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "c-{\\mathbf{b}}^{⊤}A^{-1}\\mathbf{b}",
          "type": "MathInline"
        },
        {
          "text": ". The stationary point is a minimum when ",
          "marks": [],
          "type": "Text"
