    {
      "latex": "A=\\left(\\begin{matrix}2 & 1 \\\\ 1 & 3\\end{matrix}\\right), \\mathbf{b}=\\left(\\begin{matrix}-1 \\\\ 2\\end{matrix}\\right), c=0,",
