        {
          "text": "Table 2: ",
          "marks": [
            "bold",
            "italic"
          ],
          "type": "Text"
        },
        {
          "text": "Phased rollout plan.",
          "marks": [
            "italic"
          ],
          "type": "Text"
        }
      ],
      "alignment": "center",
      "type": "Paragraph"
    },
    {
      "children": [
        {
          "text": "Total estimated effort is 1.5 engineer-months.",
          "marks": [],
          "type": "Text"
        }
      ],
