    },
    {
      "children": [
        {
          "text": "Table 1: ",
          "marks": [
            "bold",
            "italic"
          ],
          "type": "Text"
        },
        {
          "text": "Half-lives and decay constants of five isotopes.",
          "marks": [
            "italic"
          ],
          "type": "Text"
