        {
          "latex": "s_{2}",
          "type": "MathInline"
        },
        {
          "text": ", and sizes ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "n_{1}",
          "type": "MathInline"
        },
        {
          "text": " and ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "n_{2}",
          "type": "MathInline"
        },
        {
          "text": ", Welch's statistic is",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "latex": "t=\\frac{{\\bar{x}}_{1}-{\\bar{x}}_{2}}{\\sqrt{s_{1}^{2}/n_{1}+s_{2}^{2}/n_{2}}}.",
      "numbered": true,
      "label": null,
      "type": "MathBlock"
    },
    {
      "children": [
        {
          "text": "A large absolute value of ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "t",
          "type": "MathInline"
        },
        {
          "text": " means the difference between the means is large compared with its own uncertainty (",
          "marks": [],
          "type": "Text"
        },
        {
          "text": "[1]",
          "marks": [],
          "type": "Text"
        },
        {
          "text": "). Welch's form does not assume equal variances, so it is safe to use by default.",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "level": 2,
      "children": [
        {
          "text": "2.2 ",
          "marks": [],
          "type": "Text"
        },
        {
          "text": "A worked example",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "children": [
        {
          "text": "Twenty nest boxes and twenty natural cavities were checked in a single season. The fledging results are in Table ",
          "marks": [],
          "type": "Text"
        },
        {
          "text": "2",
          "marks": [],
          "type": "Text"
        },
        {
          "text": ". Applying Equation ",
          "marks": [],
          "type": "Text"
        },
        {
          "text": "3",
          "marks": [],
          "type": "Text"
        },
        {
          "text": " gives ",
