          "29.4",
          "2.4 ± 0.3"
        ],
        [
          "8",
          "3.4",
          "40.6",
          "3.7 ± 0.5"
        ],
        [
          "10",
          "1.5",
          "52.3",
          "5.2 ± 0.7"
        ]
