    {
      "level": 1,
      "children": [
        {
          "text": "Setting up the problem",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "children": [
        {
          "text": "We seek eigenstates of ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "H = H_0 + \\lambda V",
          "type": "MathInline"
        },
        {
          "text": " where the spectrum of ",
          "marks": [],
          "type": "Text"
