        {
          "latex": "H_0|n^{(0)}\\rangle = E_n^{(0)}|n^{(0)}\\rangle",
          "type": "MathInline"
        },
        {
          "text": " with non-degenerate levels, and ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "\\lambda",
          "type": "MathInline"
