          "text": " is small. Expanding",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "latex": "E_n = E_n^{(0)} + \\lambda E_n^{(1)} + \\lambda^2 E_n^{(2)} + \\cdots,\\qquad |n\\rangle = |n^{(0)}\\rangle + \\lambda|n^{(1)}\\rangle + \\cdots",
      "numbered": true,
      "label": "eq:expand",
      "type": "MathBlock"
    },
    {
      "children": [
        {
          "text": "in the Schrödinger equation and collecting powers of ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "\\lambda",
          "type": "MathInline"
        },
        {
          "text": " gives",
          "marks": [],
          "type": "Text"
