      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "latex": "x_i = \\frac{A_i / S_i}{\\sum_j A_j / S_j}.",
      "numbered": true,
      "label": "eq:quant",
      "type": "MathBlock"
    },
    {
      "level": 1,
      "children": [
        {
          "text": "Results",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "children": [
        {
          "text": "Table ",
