          "0.056"
        ],
        [
          "700",
          "458.65",
          "456.95",
          "1.09",
          "14.0",
          "0.070"
        ]
      ],
      "caption": "",
      "label": null,
      "alignment": "",
      "style": "",
      "merges": [],
      "header": false,
      "repeat_header": false,
      "shading": {},
      "type": "Table"
    },
    {
      "children": [
        {
          "text": "Table 1: ",
          "marks": [
            "bold",
            "italic"
          ],
          "type": "Text"
        },
        {
          "text": "Ti 2p₃/₂ fit results (Shirley background, pseudo-Voigt, η = 0.3). Positions and widths in eV; f is the Ti³⁺ share of the total Ti 2p area in per cent, and δ is the vacancy content in TiO₂₋δ.",
          "marks": [
            "italic"
          ],
          "type": "Text"
        }
      ],
      "alignment": "center",
      "type": "Paragraph"
    },
    {
      "children": [
        {
          "text": "The O 1s envelope requires three components: lattice O²⁻ at 530.0 eV, hydroxyl / vacancy-adjacent oxygen at 531.3 eV and adsorbed H₂O at 532.6 eV (Table ",
          "marks": [],
          "type": "Text"
        },
        {
          "text": "2",
          "marks": [],
          "type": "Text"
        },
        {
          "text": "). The lattice peak lies 71.3 eV above Ti 2p₃/₂ of Ti⁴⁺, as expected for anatase.",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "rows": [
        [
          "Component",
          "BE (eV)",
          "FWHM (eV)",
          "Area 300 °C",
          "Area 700 °C"
        ],
        [
          "O–Ti (lattice)",
          "530.0",
          "1.10",
          "88.5",
