{
  "children": [
    {
      "children": [
        {
          "text": "Setting up a reproducible Python project from scratch",
          "marks": [],
          "type": "Text"
        }
      ],
      "type": "Title"
    },
    {
      "children": [
        {
          "text": "A practical step-by-step guide",
          "marks": [],
          "type": "Text"
        }
      ],
      "type": "Author"
    },
    {
      "level": 1,
      "children": [
        {
          "text": "Prerequisites",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "ordered": false,
      "items": [
        {
          "children": [
            {
              "text": "Python 3.12 or newer, available on your PATH",
              "marks": [],
              "type": "Text"
            }
          ],
          "type": "ListItem"
        },
        {
          "children": [
            {
              "text": "Git, with your name and e-mail configured (git config user.name, git config user.email)",
              "marks": [],
              "type": "Text"
            }
          ],
          "type": "ListItem"
        },
        {
          "children": [
            {
              "text": "A terminal (bash, zsh or PowerShell)",
              "marks": [],
              "type": "Text"
            }
          ],
          "type": "ListItem"
        },
        {
          "children": [
            {
              "text": "A text editor or IDE of your choice",
              "marks": [],
              "type": "Text"
            }
          ],
          "type": "ListItem"
        }
      ],
      "type": "List"
    },
    {
      "children": [
        {
          "text": "The whole procedure takes about fifteen minutes and produces the layout shown below.",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "text": "\\begin{verbatim}\nmy-project/\n  .gitignore\n  pyproject.toml\n  src/my_project/__init__.py\n  tests/test_smoke.py\n\\end{verbatim}",
      "type": "RawLatex"
    },
    {
      "level": 1,
      "children": [
        {
          "text": "Steps",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "level": 2,
      "children": [
        {
          "text": "1. Create the project directory",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": false,
      "label": null,
      "type": "Section"
    },
    {
      "children": [
        {
          "text": "Open a terminal and run:",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "text": "\\begin{verbatim}\nmkdir my-project && cd my-project\ngit init\nmkdir -p src/my_project tests\ntouch src/my_project/__init__.py\n\\end{verbatim}",
      "type": "RawLatex"
    },
    {
      "children": [
        {
          "text": "Tip:",
          "marks": [
            "italic"
          ],
          "type": "Text"
        },
        {
          "text": " choose a short, lowercase, hyphen-separated name. Use an underscore instead of a hyphen for the importable package (my_project).",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "level": 2,
      "children": [
        {
          "text": "2. Create a virtual environment",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": false,
      "label": null,
      "type": "Section"
    },
    {
      "text": "\\begin{verbatim}\npython -m venv .venv\nsource .venv/bin/activate    # Linux / macOS\n.venv\\Scripts\\activate       # Windows\n\\end{verbatim}",
      "type": "RawLatex"
    },
    {
      "children": [
        {
          "text": "Tip:",
          "marks": [
            "italic"
          ],
          "type": "Text"
        },
        {
          "text": " put ",
          "marks": [],
          "type": "Text"
        },
        {
          "text": "/.venv/",
          "marks": [
            "code"
          ],
          "type": "Text"
        },
        {
          "text": " and ",
          "marks": [],
          "type": "Text"
        },
        {
          "text": "__pycache__/",
          "marks": [
            "code"
          ],
          "type": "Text"
        },
        {
          "text": " in your ",
          "marks": [],
          "type": "Text"
        },
        {
          "text": ".gitignore",
          "marks": [
            "code"
          ],
          "type": "Text"
        },
        {
          "text": " so they are never committed.",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "level": 2,
      "children": [
        {
          "text": "3. Declare and pin dependencies",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": false,
      "label": null,
      "type": "Section"
    },
    {
      "children": [
        {
          "text": "Describe the project in ",
          "marks": [],
          "type": "Text"
        },
        {
          "text": "pyproject.toml",
          "marks": [
            "code"
          ],
          "type": "Text"
        },
        {
          "text": ", then compile a lock file so everyone installs the same versions:",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "text": "\\begin{verbatim}\n[project]\nname = \"my-project\"\nversion = \"0.1.0\"\nrequires-python = \">=3.12\"\ndependencies = [\"numpy\"]\n\\end{verbatim}",
      "type": "RawLatex"
    },
    {
      "text": "\\begin{verbatim}\npip install pip-tools\npip-compile -o requirements.lock pyproject.toml\npip install -r requirements.lock\n\\end{verbatim}",
      "type": "RawLatex"
    },
    {
      "level": 2,
      "children": [
        {
          "text": "4. Add a test framework",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": false,
      "label": null,
      "type": "Section"
    },
    {
      "text": "\\begin{verbatim}\npip install pytest\necho 'def test_smoke(): assert True' > tests/test_smoke.py\npytest -q\n\\end{verbatim}",
      "type": "RawLatex"
    },
    {
      "children": [
        {
          "text": "A passing run prints ",
          "marks": [],
          "type": "Text"
        },
        {
          "text": "1 passed",
          "marks": [
            "code"
          ],
          "type": "Text"
        },
        {
          "text": ". From now on every change should keep it green.",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "level": 2,
      "children": [
        {
          "text": "5. Configure linting and formatting",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": false,
      "label": null,
      "type": "Section"
    },
    {
      "children": [
        {
          "text": "Ruff does both jobs in one tool:",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "text": "\\begin{verbatim}\npip install ruff\nruff check .\nruff format .\n\\end{verbatim}",
      "type": "RawLatex"
    },
    {
      "level": 2,
      "children": [
        {
          "text": "6. Make your first commit",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": false,
      "label": null,
      "type": "Section"
    },
    {
      "text": "\\begin{verbatim}\ngit add pyproject.toml requirements.lock .gitignore\ngit add src/ tests/\ngit commit -m \"Initial project skeleton\"\n\\end{verbatim}",
      "type": "RawLatex"
    },
    {
