    {
      "children": [
        {
          "text": "Adaptive mass matrices for HMC",
          "marks": [],
          "type": "Text"
        }
      ],
      "type": "Title"
    },
    {
      "children": [
        {
          "text": "A. Researcher, B. Supervisor and C. Collaborator",
          "marks": [],
          "type": "Text"
        }
      ],
      "type": "Author"
    },
    {
      "text": "\\begin{columns}\n\\column{0.5}",
      "type": "RawLatex"
    },
    {
      "text": "\\block{Motivation}{",
      "type": "RawLatex"
    },
    {
      "children": [
        {
          "text": "Bayesian inference in high-dimensional parameter spaces is slow because posteriors are strongly correlated: standard Markov chain Monte Carlo mixes poorly and tuning it by hand does not scale.",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "ordered": false,
      "items": [
        {
          "children": [
            {
              "text": "Hamiltonian Monte Carlo (HMC) follows the geometry of the posterior but needs a good mass matrix.",
              "marks": [],
              "type": "Text"
            }
          ],
          "type": "ListItem"
        },
        {
          "children": [
            {
              "text": "The No-U-Turn Sampler (NUTS) tunes the step size only, and keeps an identity or diagonal mass matrix.",
              "marks": [],
              "type": "Text"
            }
          ],
          "type": "ListItem"
        },
        {
          "children": [
            {
              "text": "We adapt a full mass matrix online, at almost no extra cost per iteration.",
              "marks": [],
              "type": "Text"
            }
          ],
          "type": "ListItem"
        }
      ],
      "type": "List"
    },
    {
      "text": "}",
      "type": "RawLatex"
    },
    {
      "text": "\\block{Method}{",
      "type": "RawLatex"
    },
    {
      "children": [
        {
          "text": "Augment the target density ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "\\pi(\\theta)",
          "type": "MathInline"
        },
        {
          "text": " with momenta ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "p \\sim \\mathcal{N}(0, M)",
          "type": "MathInline"
        },
        {
          "text": " and simulate the Hamiltonian",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "latex": "H(\\theta, p) = -\\log \\pi(\\theta) + \\tfrac{1}{2}\\, p^\\top M^{-1} p .",
      "numbered": true,
      "label": "eq:hamiltonian",
      "type": "MathBlock"
    },
    {
      "children": [
        {
          "text": "Every ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "K",
          "type": "MathInline"
        },
        {
          "text": " leapfrog steps the matrix ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "M",
          "type": "MathInline"
        },
        {
          "text": " is refreshed by a rank-one update from the covariance of the last ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "W",
          "type": "MathInline"
        },
        {
          "text": " accepted states, so ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "M",
          "type": "MathInline"
        },
        {
          "text": " converges to the posterior precision and the dynamics of Equation ",
